insert into public.activities (id, banda, saptamana, zi, pilon, titlu, durata_min, mod_default, materiale, pasi, gata_cand, nota, tema_saptamana) values
('s9-2-3-z1-fizic', '2-3', 9, 1, 'fizic'::public.pillar, 'Pași în aerul de afară', 5, 'A'::public.completion_mode, '{}'::text[], ARRAY['Ieșiți scurt pe treaptă sau în curte.', 'Mergeți 5–8 pași: „Aer. Afară.”']::text[], 'A făcut câțiva pași afară.', 'Vârsta 2–3: scurt, fără forțare; el poate refuza.', 'Vânt și aer'),
('s9-2-3-z1-mental', '2-3', 9, 1, 'mental'::public.pillar, 'Simțim aerul pe față', 3, 'A'::public.completion_mode, '{}'::text[], ARRAY['Stați pe loc afară sau la fereastră deschisă.', 'Atingeți-i obrazul ușor: „Aer pe față.”']::text[], 'A simțit aerul pe față.', 'Vârsta 2–3: scurt, fără forțare; el poate refuza.', 'Vânt și aer'),
('s9-2-3-z1-resurse', '2-3', 9, 1, 'resurse'::public.pillar, 'Șalul / haina la ușă', 4, 'A'::public.completion_mode, ARRAY['șal sau haină ușoară']::text[], ARRAY['Luați șalul sau haina împreună.', 'Puneți-l lângă ușă: „La loc, la ușă.”']::text[], 'A ajutat să pună haina la loc.', 'Vârsta 2–3: scurt, fără forțare; el poate refuza.', 'Vânt și aer'),
('s9-2-3-z1-social', '2-3', 9, 1, 'social'::public.pillar, 'Arătăm vântul cu mâna', 3, 'A'::public.completion_mode, '{}'::text[], ARRAY['Ridicați mâna în aer: „Vânt?”', 'Spuneți împreună pe scurt: „Aer.”']::text[], 'A participat la arătat.', 'Vârsta 2–3: scurt, fără forțare; el poate refuza.', 'Vânt și aer'),
('s9-2-3-z2-fizic', '2-3', 9, 2, 'fizic'::public.pillar, 'Alergăm scurt cu vântul', 5, 'A'::public.completion_mode, '{}'::text[], ARRAY['Alergați 5–10 pași pe loc plat, ținându-l de mână dacă vrea.', 'Opriți-vă: „Gata. Aer.”']::text[], 'A alergat puțin și s-a oprit.', 'Vârsta 2–3: scurt, fără forțare; el poate refuza.', 'Vânt și aer'),
('s9-2-3-z2-mental', '2-3', 9, 2, 'mental'::public.pillar, 'Frunza se mișcă', 3, 'A'::public.completion_mode, ARRAY['frunză pe jos sau pe crenguță']::text[], ARRAY['Arătați frunza care se mișcă.', '„Vânt. Frunza se mișcă.”']::text[], 'A privit frunza mișcată.', 'Vârsta 2–3: scurt, fără forțare; el poate refuza.', 'Vânt și aer'),
('s9-2-3-z2-resurse', '2-3', 9, 2, 'resurse'::public.pillar, 'Adunăm o frunză și o lăsăm', 4, 'A'::public.completion_mode, ARRAY['1 frunză']::text[], ARRAY['Luați o frunză de pe jos împreună.', 'Puneți-o înapoi pe pământ: „La loc.”']::text[], 'A luat și a lăsat frunza.', 'Vârsta 2–3: scurt, fără forțare; el poate refuza.', 'Vânt și aer'),
('s9-2-3-z2-social', '2-3', 9, 2, 'social'::public.pillar, 'Suflăm ușor împreună', 3, 'A'::public.completion_mode, '{}'::text[], ARRAY['Suflați ușor pe mâna lui: „Aer.”', 'Invitați-l să sufle pe mâna voastră, fără forțare.']::text[], 'A simțit sau a încercat să sufle.', 'Vârsta 2–3: scurt, fără forțare; el poate refuza.', 'Vânt și aer'),
('s9-2-3-z3-fizic', '2-3', 9, 3, 'fizic'::public.pillar, 'Brațele ca aripile', 4, 'A'::public.completion_mode, '{}'::text[], ARRAY['Ridicați brațele lateral: „Aripi.”', 'Mișcați-le ușor ca în vânt, de 2–3 ori.']::text[], 'A mișcat brațele.', 'Vârsta 2–3: scurt, fără forțare; el poate refuza.', 'Vânt și aer'),
('s9-2-3-z3-mental', '2-3', 9, 3, 'mental'::public.pillar, 'Unde e vântul?', 3, 'A'::public.completion_mode, '{}'::text[], ARRAY['Deschideți fereastra puțin sau ieșiți.', '„Vânt aici. Uite.”']::text[], 'A observat locul cu aer.', 'Vârsta 2–3: scurt, fără forțare; el poate refuza.', 'Vânt și aer'),
('s9-2-3-z3-resurse', '2-3', 9, 3, 'resurse'::public.pillar, 'Punga de hârtie se umflă', 4, 'A'::public.completion_mode, ARRAY['pungă de hârtie mică']::text[], ARRAY['Țineți punga deschisă la aer sau suflați ușor.', '„Aer în pungă.” Apoi puneți punga la loc.']::text[], 'A văzut punga și a ajutat la strâns.', 'Vârsta 2–3: scurt, fără forțare; el poate refuza.', 'Vânt și aer'),
('s9-2-3-z3-social', '2-3', 9, 3, 'social'::public.pillar, 'Arătăm aerul mamei / tatei', 3, 'A'::public.completion_mode, '{}'::text[], ARRAY['Duceți-l la adult: „Uite aer.”', 'Stați 1 minut, fără grabă.']::text[], 'A participat la arătat.', 'Vârsta 2–3: scurt, fără forțare; el poate refuza.', 'Vânt și aer'),
('s9-2-3-z4-fizic', '2-3', 9, 4, 'fizic'::public.pillar, 'Învârtim o eșarfă', 5, 'A'::public.completion_mode, ARRAY['eșarfă ușoară']::text[], ARRAY['Țineți eșarfa și o mișcați în aer.', 'El poate ține un colț: „Se mișcă.”']::text[], 'A ținut sau a privit eșarfa.', 'Vârsta 2–3: scurt, fără forțare; el poate refuza.', 'Vânt și aer'),
('s9-2-3-z4-mental', '2-3', 9, 4, 'mental'::public.pillar, 'Eșarfa zboară puțin', 3, 'A'::public.completion_mode, ARRAY['eșarfă']::text[], ARRAY['Lăsați eșarfa să cadă lent.', '„Jos. Aer.”']::text[], 'A urmărit căderea.', 'Vârsta 2–3: scurt, fără forțare; el poate refuza.', 'Vânt și aer')
